CREATE TABLE parents(id INT PRIMARY KEY, name VARCHAR);
CREATE TABLE children(id INT PRIMARY KEY, parent_id INT, amount INT);
INSERT INTO parents VALUES (1, 'Ada'), (2, 'Grace'), (3, 'Linus');
INSERT INTO children VALUES (10, 1, 5), (11, 1, 8), (12, 2, NULL);
SELECT (SELECT 42) AS answer;
SELECT (SELECT amount FROM children WHERE id = 999) AS missing;
SELECT (TABLE parents) AS too_many;
SELECT (SELECT id FROM parents ORDER BY id FETCH FIRST ROW ONLY) AS first_id;
SELECT (SELECT x FROM SYSTEM_RANGE(1, 9223372036854775807)) AS too_many;
SELECT (SELECT id, name FROM parents WHERE id = 1) AS parent;
SELECT (SELECT id, name FROM parents WHERE FALSE) AS parent;
SELECT p.id, (SELECT SUM(c.amount) FROM children c WHERE c.parent_id = p.id) AS total FROM parents p ORDER BY p.id;
SELECT p.id, (SELECT COUNT(*) FROM children c WHERE c.parent_id = p.id) AS total FROM parents p ORDER BY p.id;
SELECT (SELECT (SELECT p.id)) AS answer_value FROM parents p ORDER BY p.id;
SELECT (SELECT p.id FROM (VALUES 99) p(id)) AS answer_value FROM parents p ORDER BY p.id;
SELECT (SELECT p.id FROM (VALUES 99) p(other_id)) AS answer_value FROM parents p ORDER BY p.id;
SELECT p.id, (SELECT id FROM children ORDER BY id FETCH FIRST ROW ONLY) AS child FROM parents p ORDER BY p.id;
SELECT (SELECT id FROM (VALUES 99) t(other_id)) AS answer_value FROM parents p ORDER BY p.id;
SELECT p.id FROM parents p WHERE EXISTS (SELECT * FROM children c WHERE c.parent_id = p.id) ORDER BY p.id;
SELECT p.id FROM parents p WHERE NOT EXISTS (SELECT * FROM children c WHERE c.parent_id = p.id);
SELECT EXISTS(SELECT * FROM SYSTEM_RANGE(1, 9223372036854775807)) AS a, EXISTS(SELECT 1 WHERE FALSE) AS b, EXISTS(SELECT COUNT(*) FROM parents WHERE FALSE) AS c;
SELECT EXISTS(SELECT 1/x FROM SYSTEM_RANGE(0, 0)) AS failure;
SELECT EXISTS(SELECT * FROM parents LIMIT 1 OFFSET 10) AS empty;
SELECT 5 IN (SELECT amount FROM children) AS a, 4 IN (SELECT amount FROM children) AS b, NULL IN (TABLE parents) AS c, NULL IN (SELECT amount FROM children WHERE FALSE) AS d, NULL NOT IN (SELECT amount FROM children WHERE FALSE) AS e;
SELECT p.id FROM parents p WHERE p.id IN (SELECT parent_id FROM children) ORDER BY p.id;
SELECT p.id FROM parents p WHERE p.id NOT IN (SELECT parent_id FROM children) ORDER BY p.id;
SELECT p.id FROM parents p WHERE p.id IN (SELECT c.parent_id FROM children c WHERE c.parent_id = p.id) ORDER BY p.id;
SELECT p.id FROM parents p WHERE 8 IN (SELECT c.amount FROM children c WHERE c.parent_id = p.id);
SELECT (1, 2) = ROW(1, 2) AS a, (1, NULL) = (1, NULL) AS b, (1, NULL) = (2, NULL) AS c, (1, NULL) IS NOT DISTINCT FROM (1, NULL) AS d, (1, NULL) < (2, NULL) AS e;
SELECT ROW(NULL, 1) IS NULL AS a, ROW(NULL, 1) IS NOT NULL AS b, ROW(NULL, NULL) IS NULL AS c, ROW(1, 2) IS NOT NULL AS d;
SELECT (1, 2) IN (VALUES (1, 2), (3, 4)) AS a, (1, NULL) IN (VALUES (1, NULL)) AS b, (1, NULL) IN (VALUES (2, NULL)) AS c;
SELECT (1, 2) IN (SELECT 1) AS mismatch;
CREATE TABLE empty_table(id INT);
SELECT (SELECT missing FROM children) FROM empty_table;
SELECT id FROM empty_table WHERE EXISTS(SELECT missing FROM children);
SELECT (SELECT id FROM missing_table) FROM empty_table;
SELECT (SELECT id FROM parents JOIN children ON FALSE) FROM empty_table;
SELECT (SELECT t.v FROM (SELECT p.id AS v) t) AS answer_value FROM parents p ORDER BY p.id;
SELECT * FROM parents p JOIN (SELECT p.id AS v) t ON TRUE;
SELECT (SELECT MAX(x) FROM SYSTEM_RANGE(1, p.id)) AS answer_value FROM parents p ORDER BY p.id;
SELECT p.id FROM parents p WHERE EXISTS(SELECT * FROM children c JOIN (VALUES 1) t(v) ON c.parent_id = p.id) ORDER BY p.id;
SELECT p.id, (SELECT COUNT(*) FROM children c WHERE c.parent_id = p.id) AS total FROM parents p GROUP BY p.id ORDER BY p.id;
SELECT p.name, (SELECT COUNT(*) FROM children c WHERE c.parent_id = p.id) FROM parents p GROUP BY p.name;
SELECT p.id, (SELECT p.id + COUNT(*) FROM children c WHERE FALSE) AS total FROM parents p ORDER BY p.id;
SELECT (SELECT x FROM SYSTEM_RANGE(1, 10) LIMIT 1 OFFSET p.id - 1) AS answer_value FROM parents p ORDER BY p.id;
UPDATE children SET amount = (SELECT p.id * 10 FROM parents p WHERE p.id = children.parent_id);
SELECT id, amount FROM children ORDER BY id;
UPDATE children SET amount = (SELECT id FROM parents);
SELECT amount FROM children ORDER BY id;
INSERT INTO children VALUES (13, (SELECT id FROM parents WHERE id = 3), (SELECT 30));
DELETE FROM parents WHERE NOT EXISTS(SELECT 1 FROM children WHERE children.parent_id = parents.id AND children.amount < 30);
SELECT id FROM parents ORDER BY id;
SELECT CASE WHEN TRUE THEN 1 ELSE 1/0 END AS a, CASE 2 WHEN 1 THEN 1 WHEN 2 THEN 3 ELSE 1/0 END AS b, CASE NULL WHEN NULL THEN 'equal' ELSE 'fallback' END AS c, CASE WHEN FALSE THEN 1 END AS d;
SELECT CASE WHEN TRUE THEN 1 ELSE 2.5 END AS answer;
SELECT CASE WHEN TRUE THEN 1 ELSE missing END AS failure;
SELECT CASE WHEN FALSE THEN missing ELSE 1 END AS failure;
SELECT p.id, CASE WHEN EXISTS(SELECT 1 FROM children c WHERE c.parent_id = p.id) THEN 'has children' ELSE 'empty' END AS description FROM parents p ORDER BY p.id;
SELECT CASE WHEN TRUE THEN ROW(1, NULL) ELSE ROW(2, 3) END AS answer;
SELECT ROW(1) = 1 AS a, ROW(1) IN (SELECT 1) AS b, (1, NULL) BETWEEN (1, 0) AND (2, 0) AS c;
SELECT ROW(1) IN (SELECT 1) AS b, (1, NULL) BETWEEN (1, 0) AND (2, 0) AS c;
SELECT (1, 2) IN (SELECT ROW(1, 2)) AS failure;
